CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS school_students(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),admission_no text NOT NULL,first_name text NOT NULL,last_name text NOT NULL,phone text,email text,user_id uuid REFERENCES users(id),status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,admission_no));
CREATE TABLE IF NOT EXISTS school_teachers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES users(id),employee_no text NOT NULL,name text NOT NULL,status text NOT NULL DEFAULT 'active',UNIQUE(tenant_id,employee_no));
CREATE TABLE IF NOT EXISTS school_classes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,section text NOT NULL,academic_year text NOT NULL,class_teacher_id uuid REFERENCES school_teachers(id),status text NOT NULL DEFAULT 'active',UNIQUE(tenant_id,name,section,academic_year));
CREATE TABLE IF NOT EXISTS school_enrollments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),student_id uuid NOT NULL REFERENCES school_students(id),class_id uuid NOT NULL REFERENCES school_classes(id),status text NOT NULL DEFAULT 'active',enrolled_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,student_id,class_id));
CREATE TABLE IF NOT EXISTS school_attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),student_id uuid NOT NULL REFERENCES school_students(id),class_id uuid NOT NULL REFERENCES school_classes(id),attendance_date date NOT NULL,status text NOT NULL CHECK(status IN ('present','absent','late','excused')),marked_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,student_id,attendance_date));
CREATE INDEX IF NOT EXISTS idx_school_students_tenant ON school_students(tenant_id); CREATE INDEX IF NOT EXISTS idx_school_attendance_tenant_date ON school_attendance(tenant_id,attendance_date);
